func main() {
	// Simulate a password and salt
	password := "securepassword123"
	salt := make([]byte, 32)
	if _, err := rand.Read(salt); err != nil {
		fmt.Println("Error generating salt:", err)
		return
	}

	// Hash the password with PBKDF2-HMAC and SHA-256
	hash := pbkdf2.Key([]byte(password), salt, 10000, 32, sha256.New())
	hashedPassword := strings.ToUpper(hex.EncodeToString(hash))
	saltStr := hex.EncodeToString(salt)

	fmt.Printf("Hashed Password: %s\n", hashedPassword)
	fmt.Printf("Salt: %s\n", saltStr)
}

